using System;
using System.Collections.Generic;

class MinHeap {
    private List<Node> heap = new List<Node>();

    private void Swap(int i, int j) {
        var temp = heap[i];
        heap[i] = heap[j];
        heap[j] = temp;
    }

    public void Add(Node node) {
        heap.Add(node);
        int i = heap.Count - 1;
        while (i > 0)
        {
            int parent = (i - 1) / 2;
            if (heap[i].val >= heap[parent].val) break;
            Swap(i, parent);
            i = parent;
        }
    }

    public Node Pop()
    {
        if (heap.Count == 0) return null;
        Node root = heap[0];
        Node last = heap[heap.Count - 1];
        heap[0] = last;
        heap.RemoveAt(heap.Count - 1);

        int i = 0;
        while (true)
        {
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            int smallest = i;

            if (left < heap.Count && heap[left].val < heap[smallest].val)
                smallest = left;
            if (right < heap.Count && heap[right].val < heap[smallest].val)
                smallest = right;
            if (smallest == i) break;

            Swap(i, smallest);
            i = smallest;
        }

        return root;
    }

    public Node Peek()
    {
        return heap.Count > 0 ? heap[0] : null;
    }

    public int Count()
    {
        return heap.Count;
    }
}
